/**
 * 響應式狀態類型定義
 *
 * 設計理念：
 * - 借鏡 Vidstack 的 Signal 模式
 * - 提供細粒度的狀態訂閱
 * - 支援狀態變化的批量通知
 */

/**
 * 狀態變化回調
 */
export type StateSubscriber<T> = (value: T, previousValue: T) => void;

/**
 * 取消訂閱函數
 */
export type Unsubscribe = () => void;

/**
 * 響應式狀態信號接口
 */
export interface ISignal<T> {
    /** 獲取當前值 */
    get(): T;

    /** 設置新值 */
    set(value: T): void;

    /** 訂閱狀態變化 */
    subscribe(callback: StateSubscriber<T>): Unsubscribe;

    /** 取得當前訂閱者數量 */
    readonly subscriberCount: number;
}

/**
 * 媒體就緒狀態
 * 對應 HTMLMediaElement.readyState
 */
export enum ReadyState {
    /** 沒有資源 */
    HAVE_NOTHING = 0,
    /** 有元數據 */
    HAVE_METADATA = 1,
    /** 有當前幀數據 */
    HAVE_CURRENT_DATA = 2,
    /** 有未來數據可播放 */
    HAVE_FUTURE_DATA = 3,
    /** 有足夠數據可以播放 */
    HAVE_ENOUGH_DATA = 4,
}

/**
 * 網路狀態
 * 對應 HTMLMediaElement.networkState
 */
export enum NetworkState {
    /** 空狀態 */
    NETWORK_EMPTY = 0,
    /** 閒置 */
    NETWORK_IDLE = 1,
    /** 正在載入 */
    NETWORK_LOADING = 2,
    /** 沒有資源 */
    NETWORK_NO_SOURCE = 3,
}

/**
 * 媒體狀態接口
 * 包含所有可訂閱的播放器狀態
 */
export interface MediaState {
    // === 播放狀態 ===
    /** 是否暫停 */
    paused: ISignal<boolean>;
    /** 是否正在播放 */
    playing: ISignal<boolean>;
    /** 是否已結束 */
    ended: ISignal<boolean>;
    /** 是否正在 seeking */
    seeking: ISignal<boolean>;
    /** 是否正在等待數據 */
    waiting: ISignal<boolean>;

    // === 時間 ===
    /** 當前播放時間（秒） */
    currentTime: ISignal<number>;
    /** 媒體總時長（秒） */
    duration: ISignal<number>;
    /** 已緩衝時長（秒） */
    buffered: ISignal<number>;

    // === 音量 ===
    /** 音量（0-1） */
    volume: ISignal<number>;
    /** 是否靜音 */
    muted: ISignal<boolean>;

    // === 播放速率 ===
    /** 當前播放速率 */
    playbackRate: ISignal<number>;
    /** 默認播放速率 */
    defaultPlaybackRate: ISignal<number>;

    // === 尺寸 ===
    /** 視頻寬度（原始尺寸） */
    videoWidth: ISignal<number>;
    /** 視頻高度（原始尺寸） */
    videoHeight: ISignal<number>;

    // === 載入狀態 ===
    /** 就緒狀態 */
    readyState: ISignal<ReadyState>;
    /** 網路狀態 */
    networkState: ISignal<NetworkState>;

    // === 來源 ===
    /** 當前媒體來源 URL */
    src: ISignal<string>;

    // === 循環 ===
    /** 是否循環播放 */
    loop: ISignal<boolean>;

    // === HDR ===
    /** 視頻是否為 HDR */
    isHdr: ISignal<boolean>;
    /** HDR 模式是否啟用 */
    hdrModeEnabled: ISignal<boolean>;

    // === FPS ===
    /** 視頻幀率 */
    fps: ISignal<number>;

    // === 全螢幕 ===
    /** 是否全螢幕 */
    fullscreen: ISignal<boolean>;
}

/**
 * 狀態快照（用於序列化）
 */
export interface MediaStateSnapshot {
    paused: boolean;
    playing: boolean;
    ended: boolean;
    seeking: boolean;
    waiting: boolean;
    currentTime: number;
    duration: number;
    buffered: number;
    volume: number;
    muted: boolean;
    playbackRate: number;
    defaultPlaybackRate: number;
    videoWidth: number;
    videoHeight: number;
    readyState: ReadyState;
    networkState: NetworkState;
    src: string;
    loop: boolean;
    isHdr: boolean;
    hdrModeEnabled: boolean;
    fps: number;
    fullscreen: boolean;
}

/**
 * 可監聽的狀態鍵
 */
export type MediaStateKey = keyof MediaState;
